const std = @import("std");
pub const LiquidNode = struct {
    v: f32,
    tau: f32,
    bias: f32,
    w_in: f32,
    w_rec: f32,
    mu: f32,
    sigma: f32,
    A: f32,
    fn sigmoid(x: f32) f32 {
        return 1.0 / (1.0 + @exp(-x));
    }
    pub fn forward(self: *LiquidNode, x: f32, dt: f32) f32 {
        const syn_drive = self.A * sigmoid((x - self.mu) * self.sigma);
        const ltc_tau = self.tau / (1.0 + syn_drive);
        const dv_dt = -(self.v - self.bias) / ltc_tau + (self.w_in * x + self.w_rec * self.v);
        self.v += dv_dt * dt;
        return self.v;
    }
};
pub const JaideLiquidStack = struct {
    nodes: []LiquidNode,
    allocator: std.mem.Allocator,
    pub fn init(allocator: std.mem.Allocator, size: usize) !JaideLiquidStack {
        var nodes = try allocator.alloc(LiquidNode, size);
        for (nodes) |*node| {
            node.* = .{ .v = 0.0, .tau = 1.0, .bias = 0.0, .w_in = 0.1, .w_rec = 0.1, .mu = 0.0, .sigma = 1.0, .A = 1.0 };
        }
        return JaideLiquidStack{ .nodes = nodes, .allocator = allocator };
    }
    pub fn deinit(self: *JaideLiquidStack) void {
        self.allocator.free(self.nodes);
    }
    pub fn step(self: *JaideLiquidStack, inputs: []const f32, dt: f32) void {
        for (self.nodes, 0..) |*node, i| {
            const in_val = if (i < inputs.len) inputs[i] else 0.0;
            _ = node.forward(in_val, dt);
        }
    }
};
pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    var stack = try JaideLiquidStack.init(gpa.allocator(), 1024);
    defer stack.deinit();
    const mock_input = [_]f32{ 0.5, -0.2, 0.8 };
    stack.step(&mock_input, 0.01);
}
