const std = @import("std");
const math = std.math;
const mem = std.mem;
const Allocator = std.mem.Allocator;

pub const ONLINE_LR: f32 = 1e-5;
pub const ONLINE_MOMENTUM: f32 = 0.9;
pub const ONLINE_BETA2: f32 = 0.999;
pub const ONLINE_EPSILON: f32 = 1e-8;
pub const GRAD_CLIP_NORM: f32 = 1.0;
pub const SURPRISE_WEIGHT: f32 = 0.4;
pub const CREV_WEIGHT: f32 = 0.3;
pub const RANKER_WEIGHT: f32 = 0.3;
pub const ACCUMULATION_STEPS: usize = 16;
pub const MAX_DIM: usize = 2048;

pub const RewardSignal = struct {
    surprise_score: f32,
    crev_confidence_delta: f32,
    ranker_calibration_error: f32,
    combined: f32,

    pub fn compute(surprise: f32, crev_delta: f32, ranker_err: f32) RewardSignal {
        const combined = (SURPRISE_WEIGHT * surprise) +
            (CREV_WEIGHT * (1.0 - @abs(crev_delta))) +
            (RANKER_WEIGHT * (1.0 - @min(1.0, @abs(ranker_err))));
        return RewardSignal{
            .surprise_score = surprise,
            .crev_confidence_delta = crev_delta,
            .ranker_calibration_error = ranker_err,
            .combined = combined,
        };
    }
};

pub const AdamWState = struct {
    m_s: []f32,
    v_s: []f32,
    m_t: []f32,
    v_t: []f32,
    m_sb: []f32,
    v_sb: []f32,
    m_tb: []f32,
    v_tb: []f32,
    step: u64,
    dim: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, dim: usize) !AdamWState {
        const sz = dim * dim;
        const m_s = try allocator.alloc(f32, sz);
        const v_s = try allocator.alloc(f32, sz);
        const m_t = try allocator.alloc(f32, sz);
        const v_t = try allocator.alloc(f32, sz);
        const m_sb = try allocator.alloc(f32, dim);
        const v_sb = try allocator.alloc(f32, dim);
        const m_tb = try allocator.alloc(f32, dim);
        const v_tb = try allocator.alloc(f32, dim);
        @memset(m_s, 0.0);
        @memset(v_s, 0.0);
        @memset(m_t, 0.0);
        @memset(v_t, 0.0);
        @memset(m_sb, 0.0);
        @memset(v_sb, 0.0);
        @memset(m_tb, 0.0);
        @memset(v_tb, 0.0);
        return AdamWState{
            .m_s = m_s, .v_s = v_s, .m_t = m_t, .v_t = v_t,
            .m_sb = m_sb, .v_sb = v_sb, .m_tb = m_tb, .v_tb = v_tb,
            .step = 1, .dim = dim, .allocator = allocator,
        };
    }

    pub fn deinit(self: *AdamWState) void {
        self.allocator.free(self.m_s);
        self.allocator.free(self.v_s);
        self.allocator.free(self.m_t);
        self.allocator.free(self.v_t);
        self.allocator.free(self.m_sb);
        self.allocator.free(self.v_sb);
        self.allocator.free(self.m_tb);
        self.allocator.free(self.v_tb);
    }
};

pub const GradientAccumulator = struct {
    grad_s: []f32,
    grad_t: []f32,
    grad_sb: []f32,
    grad_tb: []f32,
    reward_buffer: [ACCUMULATION_STEPS]f32,
    count: usize,
    dim: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, dim: usize) !GradientAccumulator {
        const sz = dim * dim;
        const grad_s = try allocator.alloc(f32, sz);
        const grad_t = try allocator.alloc(f32, sz);
        const grad_sb = try allocator.alloc(f32, dim);
        const grad_tb = try allocator.alloc(f32, dim);
        @memset(grad_s, 0.0);
        @memset(grad_t, 0.0);
        @memset(grad_sb, 0.0);
        @memset(grad_tb, 0.0);
        return GradientAccumulator{
            .grad_s = grad_s, .grad_t = grad_t, .grad_sb = grad_sb, .grad_tb = grad_tb,
            .reward_buffer = [_]f32{0.0} ** ACCUMULATION_STEPS,
            .count = 0, .dim = dim, .allocator = allocator,
        };
    }

    pub fn deinit(self: *GradientAccumulator) void {
        self.allocator.free(self.grad_s);
        self.allocator.free(self.grad_t);
        self.allocator.free(self.grad_sb);
        self.allocator.free(self.grad_tb);
    }

    pub fn reset(self: *GradientAccumulator) void {
        @memset(self.grad_s, 0.0);
        @memset(self.grad_t, 0.0);
        @memset(self.grad_sb, 0.0);
        @memset(self.grad_tb, 0.0);
        self.reward_buffer = [_]f32{0.0} ** ACCUMULATION_STEPS;
        self.count = 0;
    }

    pub fn isFull(self: *const GradientAccumulator) bool {
        return self.count >= ACCUMULATION_STEPS;
    }
};

pub const RSFLayerOnline = struct {
    s_weight: []f32,
    t_weight: []f32,
    s_bias: []f32,
    t_bias: []f32,
    dim: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, dim: usize) !RSFLayerOnline {
        const sz = dim * dim;
        const s_weight = try allocator.alloc(f32, sz);
        const t_weight = try allocator.alloc(f32, sz);
        const s_bias = try allocator.alloc(f32, dim);
        const t_bias = try allocator.alloc(f32, dim);
        const scale = math.sqrt(2.0 / @as(f32, @floatFromInt(dim)));
        var prng = std.Random.DefaultPrng.init(42);
        const rng = prng.random();
        for (s_weight) |*w| w.* = (rng.float(f32) - 0.5) * 2.0 * scale;
        for (t_weight) |*w| w.* = (rng.float(f32) - 0.5) * 2.0 * scale;
        @memset(s_bias, 0.0);
        @memset(t_bias, 0.0);
        return RSFLayerOnline{
            .s_weight = s_weight, .t_weight = t_weight,
            .s_bias = s_bias, .t_bias = t_bias,
            .dim = dim, .allocator = allocator,
        };
    }

    pub fn deinit(self: *RSFLayerOnline) void {
        self.allocator.free(self.s_weight);
        self.allocator.free(self.t_weight);
        self.allocator.free(self.s_bias);
        self.allocator.free(self.t_bias);
    }

    pub fn forwardInPlace(self: *const RSFLayerOnline, x1: []f32, x2: []f32) void {
        const dim = self.dim;
        var s_buf: [MAX_DIM]f32 = undefined;
        var t_buf: [MAX_DIM]f32 = undefined;
        for (0..dim) |i| {
            var acc_s: f32 = self.s_bias[i];
            var acc_t: f32 = self.t_bias[i];
            for (0..dim) |j| {
                acc_s += self.s_weight[i * dim + j] * x2[j];
                acc_t += self.t_weight[i * dim + j] * x1[j];
            }
            s_buf[i] = acc_s;
            t_buf[i] = acc_t;
        }
        for (0..dim) |i| {
            x1[i] = x1[i] * @exp(@min(@max(s_buf[i], -10.0), 10.0));
            x2[i] = x2[i] + t_buf[i];
        }
    }

    pub fn inverseInPlace(self: *const RSFLayerOnline, x1: []f32, x2: []f32) void {
        const dim = self.dim;
        var s_buf: [MAX_DIM]f32 = undefined;
        var t_buf: [MAX_DIM]f32 = undefined;
        for (0..dim) |i| {
            var acc_s: f32 = self.s_bias[i];
            var acc_t: f32 = self.t_bias[i];
            for (0..dim) |j| {
                acc_s += self.s_weight[i * dim + j] * x2[j];
                acc_t += self.t_weight[i * dim + j] * x1[j];
            }
            s_buf[i] = acc_s;
            t_buf[i] = acc_t;
        }
        for (0..dim) |i| {
            x1[i] = x1[i] * @exp(-@min(@max(s_buf[i], -10.0), 10.0));
            x2[i] = x2[i] - t_buf[i];
        }
    }

    pub fn computeGradients(
        self: *const RSFLayerOnline,
        x1_pre: []const f32,
        x2_pre: []const f32,
        x1_post: []const f32,
        grad_x1_out: []const f32,
        grad_x2_out: []const f32,
        s_out: []const f32,
        grad_s_weight: []f32,
        grad_t_weight: []f32,
        grad_s_bias: []f32,
        grad_t_bias: []f32,
        reward: f32,
    ) void {
        const dim = self.dim;
        const reward_scale = reward / @as(f32, @floatFromInt(ACCUMULATION_STEPS));
        for (0..dim) |i| {
            const s_clamped = @min(@max(s_out[i], -10.0), 10.0);
            const exp_s = @exp(s_clamped);
            const d_s_i = grad_x1_out[i] * x1_pre[i] * exp_s * reward_scale;
            grad_s_bias[i] += d_s_i;
            for (0..dim) |j| grad_s_weight[i * dim + j] += d_s_i * x2_pre[j];
            const d_t_i = grad_x2_out[i] * reward_scale;
            grad_t_bias[i] += d_t_i;
            for (0..dim) |j| grad_t_weight[i * dim + j] += d_t_i * x1_post[j];
        }
    }
};

fn clipGradientNorm(grads: []f32, max_norm: f32) void {
    var norm_sq: f32 = 0.0;
    for (grads) |g| norm_sq += g * g;
    const norm = math.sqrt(norm_sq);
    if (norm > max_norm) {
        const scale = max_norm / norm;
        for (grads) |*g| g.* *= scale;
    }
}

fn adamWStep(
    weights: []f32,
    grads: []f32,
    m: []f32,
    v: []f32,
    step: u64,
    lr: f32,
    weight_decay: f32,
) void {
    const beta1: f32 = ONLINE_MOMENTUM;
    const beta2: f32 = ONLINE_BETA2;
    const eps: f32 = ONLINE_EPSILON;
    const t: f32 = @floatFromInt(step);
    const bias_corr1 = 1.0 - math.pow(f32, beta1, t);
    const bias_corr2 = 1.0 - math.pow(f32, beta2, t);
    for (0..weights.len) |i| {
        m[i] = beta1 * m[i] + (1.0 - beta1) * grads[i];
        v[i] = beta2 * v[i] + (1.0 - beta2) * grads[i] * grads[i];
        const m_hat = m[i] / bias_corr1;
        const v_hat = v[i] / bias_corr2;
        weights[i] -= lr * (m_hat / (math.sqrt(v_hat) + eps) + weight_decay * weights[i]);
    }
}

pub const OnlineLearner = struct {
    layers: []RSFLayerOnline,
    adam_states: []AdamWState,
    accumulators: []GradientAccumulator,
    num_layers: usize,
    dim: usize,
    allocator: Allocator,
    total_updates: u64,
    mutex: std.Thread.Mutex,

    pub fn init(allocator: Allocator, num_layers: usize, dim: usize) !OnlineLearner {
        const layers = try allocator.alloc(RSFLayerOnline, num_layers);
        const adam_states = try allocator.alloc(AdamWState, num_layers);
        const accumulators = try allocator.alloc(GradientAccumulator, num_layers);
        for (0..num_layers) |i| {
            layers[i] = try RSFLayerOnline.init(allocator, dim);
            adam_states[i] = try AdamWState.init(allocator, dim);
            accumulators[i] = try GradientAccumulator.init(allocator, dim);
        }
        return OnlineLearner{
            .layers = layers,
            .adam_states = adam_states,
            .accumulators = accumulators,
            .num_layers = num_layers,
            .dim = dim,
            .allocator = allocator,
            .total_updates = 0,
            .mutex = std.Thread.Mutex{},
        };
    }

    pub fn deinit(self: *OnlineLearner) void {
        for (0..self.num_layers) |i| {
            self.layers[i].deinit();
            self.adam_states[i].deinit();
            self.accumulators[i].deinit();
        }
        self.allocator.free(self.layers);
        self.allocator.free(self.adam_states);
        self.allocator.free(self.accumulators);
    }

    pub fn accumulateGradients(
        self: *OnlineLearner,
        layer_idx: usize,
        x1_pre: []const f32,
        x2_pre: []const f32,
        x1_post: []const f32,
        grad_x1: []const f32,
        grad_x2: []const f32,
        s_out: []const f32,
        reward: RewardSignal,
    ) void {
        self.mutex.lock();
        defer self.mutex.unlock();
        const acc = &self.accumulators[layer_idx];
        const layer = &self.layers[layer_idx];
        layer.computeGradients(
            x1_pre, x2_pre, x1_post, grad_x1, grad_x2, s_out,
            acc.grad_s, acc.grad_t, acc.grad_sb, acc.grad_tb,
            reward.combined,
        );
        if (acc.count < ACCUMULATION_STEPS) acc.reward_buffer[acc.count] = reward.combined;
        acc.count += 1;
        if (acc.isFull()) self.applyUpdateLocked(layer_idx);
    }

    fn applyUpdateLocked(self: *OnlineLearner, layer_idx: usize) void {
        const acc = &self.accumulators[layer_idx];
        const layer = &self.layers[layer_idx];
        const adam = &self.adam_states[layer_idx];
        clipGradientNorm(acc.grad_s, GRAD_CLIP_NORM);
        clipGradientNorm(acc.grad_t, GRAD_CLIP_NORM);
        clipGradientNorm(acc.grad_sb, GRAD_CLIP_NORM);
        clipGradientNorm(acc.grad_tb, GRAD_CLIP_NORM);
        adam.step += 1;
        adamWStep(layer.s_weight, acc.grad_s, adam.m_s, adam.v_s, adam.step, ONLINE_LR, 1e-4);
        adamWStep(layer.t_weight, acc.grad_t, adam.m_t, adam.v_t, adam.step, ONLINE_LR, 1e-4);
        adamWStep(layer.s_bias, acc.grad_sb, adam.m_sb, adam.v_sb, adam.step, ONLINE_LR, 0.0);
        adamWStep(layer.t_bias, acc.grad_tb, adam.m_tb, adam.v_tb, adam.step, ONLINE_LR, 0.0);
        acc.reset();
        self.total_updates += 1;
    }

    pub fn forwardAll(self: *const OnlineLearner, x: []f32) void {
        const half = self.dim / 2;
        const x1 = x[0..half];
        const x2 = x[half..self.dim];
        for (0..self.num_layers) |i| self.layers[i].forwardInPlace(x1, x2);
    }

    pub fn saveWeights(self: *const OnlineLearner, path: []const u8) !void {
        const file = try std.fs.cwd().createFile(path, .{});
        defer file.close();
        const writer = file.writer();
        try writer.writeInt(u64, self.num_layers, .little);
        try writer.writeInt(u64, self.dim, .little);
        for (0..self.num_layers) |i| {
            const layer = &self.layers[i];
            for (layer.s_weight) |w| try writer.writeInt(u32, @bitCast(w), .little);
            for (layer.t_weight) |w| try writer.writeInt(u32, @bitCast(w), .little);
            for (layer.s_bias) |b| try writer.writeInt(u32, @bitCast(b), .little);
            for (layer.t_bias) |b| try writer.writeInt(u32, @bitCast(b), .little);
        }
    }

    pub fn loadWeights(self: *OnlineLearner, path: []const u8) !void {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();
        const reader = file.reader();
        const num_layers = try reader.readInt(u64, .little);
        const dim = try reader.readInt(u64, .little);
        if (num_layers != self.num_layers or dim != self.dim) return error.DimensionMismatch;
        for (0..self.num_layers) |i| {
            const layer = &self.layers[i];
            for (layer.s_weight) |*w| { const b = try reader.readInt(u32, .little); w.* = @bitCast(b); }
            for (layer.t_weight) |*w| { const b = try reader.readInt(u32, .little); w.* = @bitCast(b); }
            for (layer.s_bias) |*b2| { const b = try reader.readInt(u32, .little); b2.* = @bitCast(b); }
            for (layer.t_bias) |*b2| { const b = try reader.readInt(u32, .little); b2.* = @bitCast(b); }
        }
    }

    pub fn saveAdamState(self: *const OnlineLearner, path: []const u8) !void {
        const file = try std.fs.cwd().createFile(path, .{});
        defer file.close();
        const writer = file.writer();
        try writer.writeInt(u64, self.num_layers, .little);
        try writer.writeInt(u64, self.dim, .little);
        try writer.writeInt(u64, self.total_updates, .little);
        for (0..self.num_layers) |i| {
            const adam = &self.adam_states[i];
            try writer.writeInt(u64, adam.step, .little);
            for (adam.m_s) |val| try writer.writeInt(u32, @bitCast(val), .little);
            for (adam.v_s) |val| try writer.writeInt(u32, @bitCast(val), .little);
            for (adam.m_t) |val| try writer.writeInt(u32, @bitCast(val), .little);
            for (adam.v_t) |val| try writer.writeInt(u32, @bitCast(val), .little);
            for (adam.m_sb) |val| try writer.writeInt(u32, @bitCast(val), .little);
            for (adam.v_sb) |val| try writer.writeInt(u32, @bitCast(val), .little);
            for (adam.m_tb) |val| try writer.writeInt(u32, @bitCast(val), .little);
            for (adam.v_tb) |val| try writer.writeInt(u32, @bitCast(val), .little);
        }
    }

    pub fn loadAdamState(self: *OnlineLearner, path: []const u8) !void {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();
        const reader = file.reader();
        const num_layers = try reader.readInt(u64, .little);
        const dim = try reader.readInt(u64, .little);
        if (num_layers != self.num_layers or dim != self.dim) return error.DimensionMismatch;
        self.total_updates = try reader.readInt(u64, .little);
        for (0..self.num_layers) |i| {
            const adam = &self.adam_states[i];
            adam.step = try reader.readInt(u64, .little);
            for (adam.m_s) |*v| { const b = try reader.readInt(u32, .little); v.* = @bitCast(b); }
            for (adam.v_s) |*v| { const b = try reader.readInt(u32, .little); v.* = @bitCast(b); }
            for (adam.m_t) |*v| { const b = try reader.readInt(u32, .little); v.* = @bitCast(b); }
            for (adam.v_t) |*v| { const b = try reader.readInt(u32, .little); v.* = @bitCast(b); }
            for (adam.m_sb) |*v| { const b = try reader.readInt(u32, .little); v.* = @bitCast(b); }
            for (adam.v_sb) |*v| { const b = try reader.readInt(u32, .little); v.* = @bitCast(b); }
            for (adam.m_tb) |*v| { const b = try reader.readInt(u32, .little); v.* = @bitCast(b); }
            for (adam.v_tb) |*v| { const b = try reader.readInt(u32, .little); v.* = @bitCast(b); }
        }
    }
};

pub const InternalRewardComputer = struct {
    prev_graph_energy: f32,
    prev_crev_confidence: f32,
    prev_ranker_score: f32,

    pub fn init() InternalRewardComputer {
        return InternalRewardComputer{
            .prev_graph_energy = 1.0,
            .prev_crev_confidence = 0.5,
            .prev_ranker_score = 0.5,
        };
    }

    pub fn computeReward(
        self: *InternalRewardComputer,
        current_graph_energy: f32,
        current_crev_confidence: f32,
        surprise_novelty: f32,
        current_ranker_score: f32,
    ) RewardSignal {
        const energy_delta = self.prev_graph_energy - current_graph_energy;
        const energy_reward = @min(1.0, @max(0.0, 0.5 + energy_delta * 5.0));
        const crev_delta = current_crev_confidence - self.prev_crev_confidence;
        const ranker_err = @abs(current_ranker_score - self.prev_ranker_score);
        const combined_surprise = @min(1.0, surprise_novelty * energy_reward);
        self.prev_graph_energy = current_graph_energy;
        self.prev_crev_confidence = current_crev_confidence;
        self.prev_ranker_score = current_ranker_score;
        return RewardSignal.compute(combined_surprise, crev_delta, ranker_err);
    }
};

pub const OnlineLearnerIntegration = struct {
    learner: OnlineLearner,
    reward_computer: InternalRewardComputer,
    weights_path: []const u8,
    adam_path: []const u8,
    persist_every: u64,
    allocator: Allocator,

    pub fn init(
        allocator: Allocator,
