pub const RSFLayerOnline = struct {
    s_weight: []f32,
    t_weight: []f32,
    s_bias: []f32,
    t_bias: []f32,
    dim: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, dim: usize, seed: u64) !RSFLayerOnline {
        if (dim == 0 or dim > MAX_DIM or dim % 2 != 0) return error.InvalidDimension;

        const matrix_size = try std.math.mul(usize, dim, dim);
        var layer: RSFLayerOnline = undefined;
        layer.s_weight = try allocator.alloc(f32, matrix_size);
        errdefer allocator.free(layer.s_weight);
        layer.t_weight = try allocator.alloc(f32, matrix_size);
        errdefer allocator.free(layer.t_weight);
        layer.s_bias = try allocator.alloc(f32, dim);
        errdefer allocator.free(layer.s_bias);
        layer.t_bias = try allocator.alloc(f32, dim);
        errdefer allocator.free(layer.t_bias);

        const scale = math.sqrt(2.0 / @as(f32, @floatFromInt(dim)));
        var prng = std.Random.DefaultPrng.init(seed);
        const random = prng.random();

        for (layer.s_weight) |*weight| {
            weight.* = (random.float(f32) * 2.0 - 1.0) * scale;
        }

        for (layer.t_weight) |*weight| {
            weight.* = (random.float(f32) * 2.0 - 1.0) * scale;
        }

        @memset(layer.s_bias, 0.0);
        @memset(layer.t_bias, 0.0);
        layer.dim = dim;
        layer.allocator = allocator;
        return layer;
    }

    pub fn deinit(self: *RSFLayerOnline) void {
        self.allocator.free(self.s_weight);
        self.allocator.free(self.t_weight);
        self.allocator.free(self.s_bias);
        self.allocator.free(self.t_bias);
    }

    pub fn forwardInPlace(self: *const RSFLayerOnline, x1: []f32, x2: []f32) void {
        const half_dim = self.dim / 2;

        if (x1.len != half_dim or x2.len != half_dim) return;

        var s_values: [MAX_DIM]f32 = undefined;
        var t_values: [MAX_DIM]f32 = undefined;

        for (0..half_dim) |i| {
            var s_accumulator = self.s_bias[i];
            var t_accumulator = self.t_bias[i];

            for (0..half_dim) |j| {
                s_accumulator += self.s_weight[i * self.dim + j] * x2[j];
                t_accumulator += self.t_weight[i * self.dim + j] * x1[j];
            }

            s_values[i] = @min(@max(s_accumulator, -10.0), 10.0);
            t_values[i] = t_accumulator;
        }

        for (0..half_dim) |i| {
            x1[i] *= @exp(s_values[i]);
        }

        for (0..half_dim) |i| {
            x2[i] += t_values[i];
        }
    }

    pub fn inverseInPlace(self: *const RSFLayerOnline, x1: []f32, x2: []f32) void {
        const half_dim = self.dim / 2;

        if (x1.len != half_dim or x2.len != half_dim) return;

        var s_values: [MAX_DIM]f32 = undefined;
        var t_values: [MAX_DIM]f32 = undefined;

        for (0..half_dim) |i| {
            var t_accumulator = self.t_bias[i];

            for (0..half_dim) |j| {
                t_accumulator += self.t_weight[i * self.dim + j] * x1[j];
            }

            t_values[i] = t_accumulator;
        }

        for (0..half_dim) |i| {
            x2[i] -= t_values[i];
        }

        for (0..half_dim) |i| {
            var s_accumulator = self.s_bias[i];

            for (0..half_dim) |j| {
                s_accumulator += self.s_weight[i * self.dim + j] * x2[j];
            }

            s_values[i] = @min(@max(s_accumulator, -10.0), 10.0);
        }

        for (0..half_dim) |i| {
            x1[i] *= @exp(-s_values[i]);
        }
    }

    pub fn computeGradients(
        self: *const RSFLayerOnline,
        x1_pre: []const f32,
        x2_pre: []const f32,
        x1_post: []const f32,
        grad_x1_out: []const f32,
        grad_x2_out: []const f32,
        s_out: []const f32,
        grad_s_weight: []f32,
        grad_t_weight: []f32,
        grad_s_bias: []f32,
        grad_t_bias: []f32,
        reward: f32,
    ) void {
        const half_dim = self.dim / 2;

        if (x1_pre.len != half_dim or
            x2_pre.len != half_dim or
            x1_post.len != half_dim or
            grad_x1_out.len != half_dim or
            grad_x2_out.len != half_dim or
            s_out.len != half_dim or
            grad_s_weight.len != self.dim * self.dim or
            grad_t_weight.len != self.dim * self.dim or
            grad_s_bias.len != self.dim or
            grad_t_bias.len != self.dim)
        {
            return;
        }

        const reward_scale = reward / @as(f32, @floatFromInt(ACCUMULATION_STEPS));

        for (0..half_dim) |i| {
            const s_clamped = @min(@max(s_out[i], -10.0), 10.0);
            const exp_s = @exp(s_clamped);
            const d_s = grad_x1_out[i] * x1_pre[i] * exp_s * reward_scale;
            const d_t = grad_x2_out[i] * reward_scale;

            grad_s_bias[i] += d_s;
            grad_t_bias[i] += d_t;

            for (0..half_dim) |j| {
                grad_s_weight[i * self.dim + j] += d_s * x2_pre[j];
                grad_t_weight[i * self.dim + j] += d_t * x1_post[j];
            }
        }
    }
};

fn clipGradientNorm(gradients: []f32, max_norm: f32) void {
    var squared_norm: f32 = 0.0;

    for (gradients) |gradient| {
        squared_norm += gradient * gradient;
    }

    const norm = math.sqrt(squared_norm);

    if (norm > max_norm and norm > 0.0) {
        const scale = max_norm / norm;

        for (gradients) |*gradient| {
            gradient.* *= scale;
        }
    }
}

fn adamWStep(
    weights: []f32,
    gradients: []const f32,
    first_moment: []f32,
    second_moment: []f32,
    step: u64,
    learning_rate: f32,
    weight_decay: f32,
) void {
    if (weights.len != gradients.len or
        weights.len != first_moment.len or
        weights.len != second_moment.len or
        step == 0)
    {
        return;
    }

    const beta1 = ONLINE_MOMENTUM;
    const beta2 = ONLINE_BETA2;
    const step_as_float: f32 = @floatFromInt(step);
    const bias_correction_1 = 1.0 - math.pow(f32, beta1, step_as_float);
    const bias_correction_2 = 1.0 - math.pow(f32, beta2, step_as_float);

    if (bias_correction_1 <= 0.0 or bias_correction_2 <= 0.0) return;

    for (weights, gradients, first_moment, second_moment) |*weight, gradient, *m, *v| {
        m.* = beta1 * m.* + (1.0 - beta1) * gradient;
        v.* = beta2 * v.* + (1.0 - beta2) * gradient * gradient;

        const corrected_m = m.* / bias_correction_1;
        const corrected_v = v.* / bias_correction_2;
        const adaptive_update = corrected_m / (math.sqrt(corrected_v) + ONLINE_EPSILON);

        weight.* -= learning_rate * (adaptive_update + weight_decay * weight.*);
    }
}

pub const OnlineLearner = struct {
    layers: []RSFLayerOnline,
    adam_states: []AdamWState,
    accumulators: []GradientAccumulator,
    num_layers: usize,
    dim: usize,
    allocator: Allocator,
    total_updates: u64,
    mutex: std.Thread.Mutex,

    pub fn init(allocator: Allocator, num_layers: usize, dim: usize) !OnlineLearner {
        if (num_layers == 0 or dim == 0 or dim > MAX_DIM or dim % 2 != 0) {
            return error.InvalidConfiguration;
        }

        const layers = try allocator.alloc(RSFLayerOnline, num_layers);
        errdefer allocator.free(layers);

        const adam_states = try allocator.alloc(AdamWState, num_layers);
        errdefer allocator.free(adam_states);

        const accumulators = try allocator.alloc(GradientAccumulator, num_layers);
        errdefer allocator.free(accumulators);

        var initialized_layers: usize = 0;
        errdefer {
            for (0..initialized_layers) |i| {
                layers[i].deinit();
                adam_states[i].deinit();
                accumulators[i].deinit();
            }
        }

        for (0..num_layers) |i| {
            layers[i] = try RSFLayerOnline.init(allocator, dim, @as(u64, @intCast(i + 1)) * 0x9e3779b97f4a7c15);
            adam_states[i] = try AdamWState.init(allocator, dim);
            accumulators[i] = try GradientAccumulator.init(allocator, dim);
            initialized_layers += 1;
        }

        return .{
            .layers = layers,
            .adam_states = adam_states,
            .accumulators = accumulators,
            .num_layers = num_layers,
            .dim = dim,
            .allocator = allocator,
            .total_updates = 0,
            .mutex = .{},
        };
    }

    pub fn deinit(self: *OnlineLearner) void {
        for (0..self.num_layers) |i| {
            self.layers[i].deinit();
            self.adam_states[i].deinit();
            self.accumulators[i].deinit();
        }

        self.allocator.free(self.layers);
        self.allocator.free(self.adam_states);
        self.allocator.free(self.accumulators);
    }

    pub fn accumulateGradients(
        self: *OnlineLearner,
        layer_idx: usize,
        x1_pre: []const f32,
        x2_pre: []const f32,
        x1_post: []const f32,
        grad_x1: []const f32,
        grad_x2: []const f32,
        s_out: []const f32,
        reward: RewardSignal,
    ) !void {
        if (layer_idx >= self.num_layers) return error.InvalidLayerIndex;

        self.mutex.lock();
        defer self.mutex.unlock();

        const accumulator = &self.accumulators[layer_idx];
        const layer = &self.layers[layer_idx];

        layer.computeGradients(
            x1_pre,
            x2_pre,
            x1_post,
            grad_x1,
            grad_x2,
            s_out,
            accumulator.grad_s,
            accumulator.grad_t,
            accumulator.grad_sb,
            accumulator.grad_tb,
            reward.combined,
        );

        if (accumulator.count < ACCUMULATION_STEPS) {
            accumulator.reward_buffer[accumulator.count] = reward.combined;
        }

        accumulator.count += 1;

        if (accumulator.isFull()) {
            self.applyUpdateLocked(layer_idx);
        }
    }

    fn applyUpdateLocked(self: *OnlineLearner, layer_idx: usize) void {
        const accumulator = &self.accumulators[layer_idx];
        const layer = &self.layers[layer_idx];
        const adam = &self.adam_states[layer_idx];

        clipGradientNorm(accumulator.grad_s, GRAD_CLIP_NORM);
        clipGradientNorm(accumulator.grad_t, GRAD_CLIP_NORM);
        clipGradientNorm(accumulator.grad_sb, GRAD_CLIP_NORM);
        clipGradientNorm(accumulator.grad_tb, GRAD_CLIP_NORM);

        adam.step += 1;

        adamWStep(layer.s_weight, accumulator.grad_s, adam.m_s, adam.v_s, adam.step, ONLINE_LR, 1e-4);
        adamWStep(layer.t_weight, accumulator.grad_t, adam.m_t, adam.v_t, adam.step, ONLINE_LR, 1e-4);
        adamWStep(layer.s_bias, accumulator.grad_sb, adam.m_sb, adam.v_sb, adam.step, ONLINE_LR, 0.0);
        adamWStep(layer.t_bias, accumulator.grad_tb, adam.m_tb, adam.v_tb, adam.step, ONLINE_LR, 0.0);

        accumulator.reset();
        self.total_updates += 1;
    }

    pub fn forwardAll(self: *const OnlineLearner, x: []f32) !void {
        if (x.len != self.dim) return error.DimensionMismatch;

        const half_dim = self.dim / 2;
        const x1 = x[0..half_dim];
        const x2 = x[half_dim..];

        for (self.layers) |*layer| {
            layer.forwardInPlace(x1, x2);
        }
    }

    pub fn saveWeights(self: *const OnlineLearner, path: []const u8) !void {
        const file = try std.fs.cwd().createFile(path, .{ .truncate = true });
        defer file.close();

        const writer = file.writer();

        try writer.writeInt(u64, @intCast(self.num_layers), .little);
        try writer.writeInt(u64, @intCast(self.dim), .little);

        for (self.layers) |layer| {
            for (layer.s_weight) |weight| {
                try writer.writeInt(u32, @bitCast(weight), .little);
            }

            for (layer.t_weight) |weight| {
                try writer.writeInt(u32, @bitCast(weight), .little);
            }

            for (layer.s_bias) |bias| {
                try writer.writeInt(u32, @bitCast(bias), .little);
            }

            for (layer.t_bias) |bias| {
                try writer.writeInt(u32, @bitCast(bias), .little);
            }
        }
    }

    pub fn loadWeights(self: *OnlineLearner, path: []const u8) !void {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();

        const reader = file.reader();
        const stored_num_layers = try reader.readInt(u64, .little);
        const stored_dim = try reader.readInt(u64, .little);

        if (stored_num_layers != self.num_layers or stored_dim != self.dim) {
            return error.DimensionMismatch;
        }

        for (self.layers) |*layer| {
            for (layer.s_weight) |*weight| {
                weight.* = @bitCast(try reader.readInt(u32, .little));
            }

            for (layer.t_weight) |*weight| {
                weight.* = @bitCast(try reader.readInt(u32, .little));
            }

            for (layer.s_bias) |*bias| {
                bias.* = @bitCast(try reader.readInt(u32, .little));
            }

            for (layer.t_bias) |*bias| {
                bias.* = @bitCast(try reader.readInt(u32, .little));
            }
        }
    }

    pub fn saveAdamState(self: *const OnlineLearner, path: []const u8) !void {
        const file = try std.fs.cwd().createFile(path, .{ .truncate = true });
        defer file.close();

        const writer = file.writer();

        try writer.writeInt(u64, @intCast(self.num_layers), .little);
        try writer.writeInt(u64, @intCast(self.dim), .little);
        try writer.writeInt(u64, self.total_updates, .little);

        for (self.adam_states) |state| {
            try writer.writeInt(u64, state.step, .little);

            for (state.m_s) |value| try writer.writeInt(u32, @bitCast(value), .little);
            for (state.v_s) |value| try writer.writeInt(u32, @bitCast(value), .little);
            for (state.m_t) |value| try writer.writeInt(u32, @bitCast(value), .little);
            for (state.v_t) |value| try writer.writeInt(u32, @bitCast(value), .little);
            for (state.m_sb) |value| try writer.writeInt(u32, @bitCast(value), .little);
            for (state.v_sb) |value| try writer.writeInt(u32, @bitCast(value), .little);
            for (state.m_tb) |value| try writer.writeInt(u32, @bitCast(value), .little);
            for (state.v_tb) |value| try writer.writeInt(u32, @bitCast(value), .little);
        }
    }

    pub fn loadAdamState(self: *OnlineLearner, path: []const u8) !void {
        const file = try std.fs.cwd().openFile(path, .{});
        defer file.close();

        const reader = file.reader();
        const stored_num_layers = try reader.readInt(u64, .little);
        const stored_dim = try reader.readInt(u64, .little);

        if (stored_num_layers != self.num_layers or stored_dim != self.dim) {
            return error.DimensionMismatch;
        }

        self.total_updates = try reader.readInt(u64, .little);

        for (self.adam_states) |*state| {
            state.step = try reader.readInt(u64, .little);

            for (state.m_s) |*value| value.* = @bitCast(try reader.readInt(u32, .little));
            for (state.v_s) |*value| value.* = @bitCast(try reader.readInt(u32, .little));
            for (state.m_t) |*value| value.* = @bitCast(try reader.readInt(u32, .little));
            for (state.v_t) |*value| value.* = @bitCast(try reader.readInt(u32, .little));
            for (state.m_sb) |*value| value.* = @bitCast(try reader.readInt(u32, .little));
            for (state.v_sb) |*value| value.* = @bitCast(try reader.readInt(u32, .little));
            for (state.m_tb) |*value| value.* = @bitCast(try reader.readInt(u32, .little));
            for (state.v_tb) |*value| value.* = @bitCast(try reader.readInt(u32, .little));
        }
    }
};

pub const InternalRewardComputer = struct {
    previous_graph_energy: f32,
    previous_crev_confidence: f32,
    previous_ranker_score: f32,

    pub fn init() InternalRewardComputer {
        return .{
            .previous_graph_energy = 1.0,
            .previous_crev_confidence = 0.5,
            .previous_ranker_score = 0.5,
        };
    }

    pub fn computeReward(
        self: *InternalRewardComputer,
        current_graph_energy: f32,
        current_crev_confidence: f32,
        surprise_novelty: f32,
        current_ranker_score: f32,
    ) RewardSignal {
        const energy_delta = self.previous_graph_energy - current_graph_energy;
        const energy_reward = @min(1.0, @max(0.0, 0.5 + energy_delta * 5.0));
        const crev_delta = current_crev_confidence - self.previous_crev_confidence;
        const ranker_error = @abs(current_ranker_score - self.previous_ranker_score);
        const scaled_surprise = @min(1.0, @max(0.0, surprise_novelty * energy_reward));

        self.previous_graph_energy = current_graph_energy;
        self.previous_crev_confidence = current_crev_confidence;
        self.previous_ranker_score = current_ranker_score;

        return RewardSignal.compute(scaled_surprise, crev_delta, ranker_error);
    }
};

pub const OnlineLearnerIntegration = struct {
    learner: OnlineLearner,
    reward_computer: InternalRewardComputer,
    weights_path: []const u8,
    adam_path: []const u8,
    persist_every: u64,
    allocator: Allocator,

    pub fn init(
        allocator: Allocator,
        num_layers: usize,
        dim: usize,
        weights_path: []const u8,
        adam_path: []const u8,
        persist_every: u64,
    ) !OnlineLearnerIntegration {
        if (persist_every == 0) return error.InvalidPersistenceInterval;

        var learner = try OnlineLearner.init(allocator, num_layers, dim);
        errdefer learner.deinit();

        learner.loadWeights(weights_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => return err,
        };

        learner.loadAdamState(adam_path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => return err,
        };

        return .{
            .learner = learner,
            .reward_computer = InternalRewardComputer.init(),
            .weights_path = try allocator.dupe(u8, weights_path),
            .adam_path = try allocator.dupe(u8, adam_path),
            .persist_every = persist_every,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *OnlineLearnerIntegration) void {
        self.learner.deinit();
        self.allocator.free(self.weights_path);
        self.allocator.free(self.adam_path);
    }

    pub fn processInteraction(
        self: *OnlineLearnerIntegration,
        layer_idx: usize,
        x1_pre: []const f32,
        x2_pre: []const f32,
        x1_post: []const f32,
        grad_x1: []const f32,
        grad_x2: []const f32,
        s_out: []const f32,
        graph_energy: f32,
        crev_confidence: f32,
        surprise_novelty: f32,
        ranker_score: f32,
    ) !void {
        const reward = self.reward_computer.computeReward(
            graph_energy,
            crev_confidence,
            surprise_novelty,
            ranker_score,
        );

        const updates_before = self.learner.total_updates;

        try self.learner.accumulateGradients(
            layer_idx,
            x1_pre,
            x2_pre,
            x1_post,
            grad_x1,
            grad_x2,
            s_out,
            reward,
        );

        if (self.learner.total_updates > updates_before and
            self.learner.total_updates % self.persist_every == 0)
        {
            try self.learner.saveWeights(self.weights_path);
            try self.learner.saveAdamState(self.adam_path);
        }
    }

    pub fn forwardAll(self: *const OnlineLearnerIntegration, x: []f32) !void {
        try self.learner.forwardAll(x);
    }

    pub fn flush(self: *OnlineLearnerIntegration) !void {
        self.learner.mutex.lock();
        defer self.learner.mutex.unlock();

        for (0..self.learner.num_layers) |layer_idx| {
            if (self.learner.accumulators[layer_idx].count > 0) {
                self.learner.applyUpdateLocked(layer_idx);
            }
        }

        try self.learner.saveWeights(self.weights_path);
        try self.learner.saveAdamState(self.adam_path);
    }
};
