const std = @import("std");
const sfd = @import("../optimizer/sfd.zig");
const esso = @import("../core/relational/esso_optimizer.zig");

const Allocator = std.mem.Allocator;

pub const SURPRISE_WEIGHT: f64 = 0.4;
pub const CREV_WEIGHT: f64 = 0.3;
pub const RANKER_WEIGHT: f64 = 0.3;
pub const ACCUMULATION_STEPS: usize = 16;

pub const RewardSignal = struct {
    surprise_score: f64,
    crev_confidence_delta: f64,
    ranker_calibration_error: f64,
    combined: f64,

    pub fn compute(surprise: f64, crev_delta: f64, ranker_error: f64) RewardSignal {
        const bounded_surprise = std.math.clamp(surprise, 0.0, 1.0);
        const bounded_crev_delta = std.math.clamp(@abs(crev_delta), 0.0, 1.0);
        const bounded_ranker_error = std.math.clamp(@abs(ranker_error), 0.0, 1.0);

        return .{
            .surprise_score = bounded_surprise,
            .crev_confidence_delta = crev_delta,
            .ranker_calibration_error = bounded_ranker_error,
            .combined = std.math.clamp(
                SURPRISE_WEIGHT * bounded_surprise +
                    CREV_WEIGHT * (1.0 - bounded_crev_delta) +
                    RANKER_WEIGHT * (1.0 - bounded_ranker_error),
                0.0,
                1.0,
            ),
        };
    }
};

pub const InternalRewardComputer = struct {
    previous_graph_energy: f64,
    previous_crev_confidence: f64,
    previous_ranker_score: f64,

    pub fn init() InternalRewardComputer {
        return .{
            .previous_graph_energy = 1.0,
            .previous_crev_confidence = 0.5,
            .previous_ranker_score = 0.5,
        };
    }

    pub fn computeReward(
        self: *InternalRewardComputer,
        graph_energy: f64,
        crev_confidence: f64,
        surprise_novelty: f64,
        ranker_score: f64,
    ) RewardSignal {
        const graph_energy_delta = self.previous_graph_energy - graph_energy;
        const energy_reward = std.math.clamp(0.5 + graph_energy_delta * 5.0, 0.0, 1.0);
        const crev_delta = crev_confidence - self.previous_crev_confidence;
        const ranker_error = @abs(ranker_score - self.previous_ranker_score);
        const surprise = std.math.clamp(surprise_novelty * energy_reward, 0.0, 1.0);

        self.previous_graph_energy = graph_energy;
        self.previous_crev_confidence = crev_confidence;
        self.previous_ranker_score = ranker_score;

        return RewardSignal.compute(surprise, crev_delta, ranker_error);
    }
};

pub const OnlineParameterSet = struct {
    values: []f64,
    gradients: []f64,
    accumulated_gradients: []f64,
    element_count: usize,
    accumulation_count: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, values: []f64) !OnlineParameterSet {
        const gradients = try allocator.alloc(f64, values.len);
        errdefer allocator.free(gradients);

        const accumulated_gradients = try allocator.alloc(f64, values.len);
        errdefer allocator.free(accumulated_gradients);

        @memset(gradients, 0.0);
        @memset(accumulated_gradients, 0.0);

        return .{
            .values = values,
            .gradients = gradients,
            .accumulated_gradients = accumulated_gradients,
            .element_count = values.len,
            .accumulation_count = 0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *OnlineParameterSet) void {
        self.allocator.free(self.gradients);
        self.allocator.free(self.accumulated_gradients);
    }

    pub fn clearGradients(self: *OnlineParameterSet) void {
        @memset(self.gradients, 0.0);
    }

    pub fn clearAccumulatedGradients(self: *OnlineParameterSet) void {
        @memset(self.accumulated_gradients, 0.0);
        self.accumulation_count = 0;
    }

    pub fn accumulate(self: *OnlineParameterSet, reward: f64) !void {
        if (self.gradients.len != self.accumulated_gradients.len) {
            return error.GradientDimensionMismatch;
        }

        const scale = std.math.clamp(reward, -1.0, 1.0);

        for (self.gradients, self.accumulated_gradients) |gradient, *accumulated| {
            accumulated.* += gradient * scale;
        }

        self.accumulation_count += 1;
    }

    pub fn averageAccumulatedGradients(self: *OnlineParameterSet) void {
        if (self.accumulation_count == 0) return;

        const divisor: f64 = @floatFromInt(self.accumulation_count);

        for (self.accumulated_gradients) |*gradient| {
            gradient.* /= divisor;
        }
    }
};

pub const OnlineOptimizationConfig = struct {
    sfd_learning_rate: f64,
    esso_iterations: usize,
    esso_initial_temperature: f64,
    esso_cooling_rate: f64,
    accumulation_steps: usize,

    pub fn default() OnlineOptimizationConfig {
        return .{
            .sfd_learning_rate = 1e-5,
            .esso_iterations = 32,
            .esso_initial_temperature = 0.05,
            .esso_cooling_rate = 0.95,
            .accumulation_steps = ACCUMULATION_STEPS,
        };
    }

    pub fn validate(self: OnlineOptimizationConfig) !void {
        if (!std.math.isFinite(self.sfd_learning_rate) or self.sfd_learning_rate <= 0.0) {
            return error.InvalidSFDLearningRate;
        }

        if (self.esso_iterations == 0) {
            return error.InvalidESSOIterations;
        }

        if (!std.math.isFinite(self.esso_initial_temperature) or self.esso_initial_temperature <= 0.0) {
            return error.InvalidESSOTemperature;
        }

        if (!std.math.isFinite(self.esso_cooling_rate) or self.esso_cooling_rate <= 0.0 or self.esso_cooling_rate >= 1.0) {
            return error.InvalidESSOCoolingRate;
        }

        if (self.accumulation_steps == 0) {
            return error.InvalidAccumulationSteps;
        }
    }
};

pub const OnlineOptimizer = struct {
    sfd_optimizer: sfd.SpectralFisherDescent,
    esso_optimizer: esso.EntangledStochasticSymmetryOptimizer,
    parameter_sets: std.ArrayList(OnlineParameterSet),
    config: OnlineOptimizationConfig,
    update_count: u64,
    mutex: std.Thread.Mutex,
    allocator: Allocator,

    pub fn init(
        allocator: Allocator,
        config: OnlineOptimizationConfig,
    ) !OnlineOptimizer {
        try config.validate();

        return .{
            .sfd_optimizer = try sfd.SpectralFisherDescent.init(allocator, config.sfd_learning_rate),
            .esso_optimizer = esso.EntangledStochasticSymmetryOptimizer.init(
                allocator,
                config.esso_initial_temperature,
                config.esso_cooling_rate,
                config.esso_iterations,
            ),
            .parameter_sets = std.ArrayList(OnlineParameterSet).init(allocator),
            .config = config,
            .update_count = 0,
            .mutex = .{},
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *OnlineOptimizer) void {
        self.mutex.lock();
        defer self.mutex.unlock();

        for (self.parameter_sets.items) |*parameter_set| {
            parameter_set.deinit();
        }

        self.parameter_sets.deinit();
        self.sfd_optimizer.deinit();
        self.esso_optimizer.deinit();
    }

    pub fn registerParameterSet(self: *OnlineOptimizer, values: []f64) !usize {
        if (values.len == 0) return error.EmptyParameterSet;

        self.mutex.lock();
        defer self.mutex.unlock();

        const parameter_set = try OnlineParameterSet.init(self.allocator, values);
        errdefer {
            var mutable_parameter_set = parameter_set;
            mutable_parameter_set.deinit();
        }

        try self.parameter_sets.append(parameter_set);
        return self.parameter_sets.items.len - 1;
    }

    pub fn clearGradients(self: *OnlineOptimizer, parameter_set_index: usize) !void {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (parameter_set_index >= self.parameter_sets.items.len) {
            return error.InvalidParameterSetIndex;
        }

        self.parameter_sets.items[parameter_set_index].clearGradients();
    }

    pub fn setGradient(
        self: *OnlineOptimizer,
        parameter_set_index: usize,
        parameter_index: usize,
        gradient: f64,
    ) !void {
        if (!std.math.isFinite(gradient)) return error.NonFiniteGradient;

        self.mutex.lock();
        defer self.mutex.unlock();

        if (parameter_set_index >= self.parameter_sets.items.len) {
            return error.InvalidParameterSetIndex;
        }

        const parameter_set = &self.parameter_sets.items[parameter_set_index];

        if (parameter_index >= parameter_set.gradients.len) {
            return error.InvalidParameterIndex;
        }

        parameter_set.gradients[parameter_index] = gradient;
    }

    pub fn addGradient(
        self: *OnlineOptimizer,
        parameter_set_index: usize,
        parameter_index: usize,
        gradient_delta: f64,
    ) !void {
        if (!std.math.isFinite(gradient_delta)) return error.NonFiniteGradient;

        self.mutex.lock();
        defer self.mutex.unlock();

        if (parameter_set_index >= self.parameter_sets.items.len) {
            return error.InvalidParameterSetIndex;
        }

        const parameter_set = &self.parameter_sets.items[parameter_set_index];

        if (parameter_index >= parameter_set.gradients.len) {
            return error.InvalidParameterIndex;
        }

        const updated_gradient = parameter_set.gradients[parameter_index] + gradient_delta;

        if (!std.math.isFinite(updated_gradient)) {
            return error.NonFiniteGradient;
        }

        parameter_set.gradients[parameter_index] = updated_gradient;
    }

    pub fn accumulateRewardedGradients(
        self: *OnlineOptimizer,
        parameter_set_index: usize,
        reward: RewardSignal,
    ) !bool {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (parameter_set_index >= self.parameter_sets.items.len) {
            return error.InvalidParameterSetIndex;
        }

        const parameter_set = &self.parameter_sets.items[parameter_set_index];
        try parameter_set.accumulate(reward.combined);

        return parameter_set.accumulation_count >= self.config.accumulation_steps;
    }

    pub fn applySFD(self: *OnlineOptimizer, parameter_set_index: usize) !void {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (parameter_set_index >= self.parameter_sets.items.len) {
            return error.InvalidParameterSetIndex;
        }

        const parameter_set = &self.parameter_sets.items[parameter_set_index];

        if (parameter_set.accumulation_count == 0) {
            return error.NoAccumulatedGradients;
        }

        parameter_set.averageAccumulatedGradients();

        try self.sfd_optimizer.step(
            parameter_set.values,
            parameter_set.accumulated_gradients,
        );

        parameter_set.clearAccumulatedGradients();
        parameter_set.clearGradients();
        self.update_count += 1;
    }

    pub fn optimizeESSO(
        self: *OnlineOptimizer,
        graph_context: *esso.GraphContext,
    ) !void {
        self.mutex.lock();
        defer self.mutex.unlock();

        try self.esso_optimizer.optimize(graph_context);
    }

    pub fn applySFDAndESSO(
        self: *OnlineOptimizer,
        parameter_set_index: usize,
        graph_context: *esso.GraphContext,
    ) !void {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (parameter_set_index >= self.parameter_sets.items.len) {
            return error.InvalidParameterSetIndex;
        }

        const parameter_set = &self.parameter_sets.items[parameter_set_index];

        if (parameter_set.accumulation_count == 0) {
            return error.NoAccumulatedGradients;
        }

        parameter_set.averageAccumulatedGradients();

        try self.sfd_optimizer.step(
            parameter_set.values,
            parameter_set.accumulated_gradients,
        );

        parameter_set.clearAccumulatedGradients();
        parameter_set.clearGradients();
        self.update_count += 1;

        try self.esso_optimizer.optimize(graph_context);
    }

    pub fn flushSFD(self: *OnlineOptimizer, parameter_set_index: usize) !bool {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (parameter_set_index >= self.parameter_sets.items.len) {
            return error.InvalidParameterSetIndex;
        }

        const parameter_set = &self.parameter_sets.items[parameter_set_index];

        if (parameter_set.accumulation_count == 0) {
            return false;
        }

        parameter_set.averageAccumulatedGradients();

        try self.sfd_optimizer.step(
            parameter_set.values,
            parameter_set.accumulated_gradients,
        );

        parameter_set.clearAccumulatedGradients();
        parameter_set.clearGradients();
        self.update_count += 1;

        return true;
    }

    pub fn parameterSetCount(self: *const OnlineOptimizer) usize {
        return self.parameter_sets.items.len;
    }

    pub fn getUpdateCount(self: *const OnlineOptimizer) u64 {
        return self.update_count;
    }
};

pub const OnlineLearningController = struct {
    optimizer: OnlineOptimizer,
    reward_computer: InternalRewardComputer,
    allocator: Allocator,

    pub fn init(
        allocator: Allocator,
        config: OnlineOptimizationConfig,
    ) !OnlineLearningController {
        return .{
            .optimizer = try OnlineOptimizer.init(allocator, config),
            .reward_computer = InternalRewardComputer.init(),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *OnlineLearningController) void {
        self.optimizer.deinit();
    }

    pub fn registerParameters(self: *OnlineLearningController, values: []f64) !usize {
        return self.optimizer.registerParameterSet(values);
    }

    pub fn recordGradient(
        self: *OnlineLearningController,
        parameter_set_index: usize,
        parameter_index: usize,
        gradient: f64,
    ) !void {
        try self.optimizer.addGradient(parameter_set_index, parameter_index, gradient);
    }

    pub fn commitInteraction(
        self: *OnlineLearningController,
        parameter_set_index: usize,
        graph_context: *esso.GraphContext,
        graph_energy: f64,
        crev_confidence: f64,
        surprise_novelty: f64,
        ranker_score: f64,
    ) !void {
        const reward = self.reward_computer.computeReward(
            graph_energy,
            crev_confidence,
            surprise_novelty,
            ranker_score,
        );

        const ready_for_update = try self.optimizer.accumulateRewardedGradients(
            parameter_set_index,
            reward,
        );

        if (ready_for_update) {
            try self.optimizer.applySFDAndESSO(parameter_set_index, graph_context);
        }
    }

    pub fn flush(
        self: *OnlineLearningController,
        parameter_set_index: usize,
        graph_context: *esso.GraphContext,
    ) !void {
        const applied = try self.optimizer.flushSFD(parameter_set_index);

        if (applied) {
            try self.optimizer.optimizeESSO(graph_context);
        }
    }
};
