pub const SURPRISE_WEIGHT: f64 = 0.4;
pub const CREV_WEIGHT: f64 = 0.3;
pub const RANKER_WEIGHT: f64 = 0.3;
pub const ACCUMULATION_STEPS: usize = 16;
pub const MAX_SAFE_ACCUMULATION_STEPS: usize = 1_048_576;
pub const MAX_SFD_LEARNING_RATE: f64 = 1.0;
pub const MIN_SFD_LEARNING_RATE: f64 = 1e-12;
pub const MAX_GRAPH_ENERGY: f64 = 1e300;
pub const MAX_CONFIDENCE: f64 = 1.0;
pub const MIN_CONFIDENCE: f64 = 0.0;
pub const MAX_REWARD_INPUT: f64 = 1.0;
pub const MIN_REWARD_INPUT: f64 = 0.0;

pub const GraphEnergyDirection = enum {
    lower_is_better,
    higher_is_better,
};

pub const RewardSignal = struct {
    surprise_score: f64,
    crev_confidence_delta: f64,
    ranker_calibration_error: f64,
    combined: f64,

    pub fn compute(surprise: f64, crev_delta: f64, ranker_error: f64) !RewardSignal {
        if (!std.math.isFinite(surprise) or !std.math.isFinite(crev_delta) or !std.math.isFinite(ranker_error)) {
            return error.NonFiniteRewardInput;
        }

        const bounded_surprise = std.math.clamp(surprise, MIN_REWARD_INPUT, MAX_REWARD_INPUT);
        const bounded_crev_delta = std.math.clamp(crev_delta, -1.0, 1.0);
        const bounded_ranker_error = std.math.clamp(@abs(ranker_error), MIN_REWARD_INPUT, MAX_REWARD_INPUT);

        return .{
            .surprise_score = bounded_surprise,
            .crev_confidence_delta = bounded_crev_delta,
            .ranker_calibration_error = bounded_ranker_error,
            .combined = std.math.clamp(
                SURPRISE_WEIGHT * bounded_surprise +
                    CREV_WEIGHT * (1.0 - @abs(bounded_crev_delta)) +
                    RANKER_WEIGHT * (1.0 - bounded_ranker_error),
                MIN_REWARD_INPUT,
                MAX_REWARD_INPUT,
            ),
        };
    }
};

pub const InternalRewardConfig = struct {
    initial_graph_energy: f64,
    initial_crev_confidence: f64,
    initial_ranker_score: f64,
    graph_energy_direction: GraphEnergyDirection,
    graph_energy_scale: f64,

    pub fn validate(self: InternalRewardConfig) !void {
        if (!std.math.isFinite(self.initial_graph_energy) or
            @abs(self.initial_graph_energy) > MAX_GRAPH_ENERGY)
        {
            return error.InvalidInitialGraphEnergy;
        }

        if (!std.math.isFinite(self.initial_crev_confidence) or
            self.initial_crev_confidence < MIN_CONFIDENCE or
            self.initial_crev_confidence > MAX_CONFIDENCE)
        {
            return error.InvalidInitialCREVConfidence;
        }

        if (!std.math.isFinite(self.initial_ranker_score) or
            self.initial_ranker_score < MIN_CONFIDENCE or
            self.initial_ranker_score > MAX_CONFIDENCE)
        {
            return error.InvalidInitialRankerScore;
        }

        if (!std.math.isFinite(self.graph_energy_scale) or self.graph_energy_scale <= 0.0) {
            return error.InvalidGraphEnergyScale;
        }
    }

    pub fn default() InternalRewardConfig {
        return .{
            .initial_graph_energy = 1.0,
            .initial_crev_confidence = 0.5,
            .initial_ranker_score = 0.5,
            .graph_energy_direction = .lower_is_better,
            .graph_energy_scale = 5.0,
        };
    }
};

pub const InternalRewardComputer = struct {
    previous_graph_energy: f64,
    previous_crev_confidence: f64,
    previous_ranker_score: f64,
    config: InternalRewardConfig,

    pub fn init(config: InternalRewardConfig) !InternalRewardComputer {
        try config.validate();

        return .{
            .previous_graph_energy = config.initial_graph_energy,
            .previous_crev_confidence = config.initial_crev_confidence,
            .previous_ranker_score = config.initial_ranker_score,
            .config = config,
        };
    }

    pub fn computeReward(
        self: *InternalRewardComputer,
        graph_energy: f64,
        crev_confidence: f64,
        surprise_novelty: f64,
        ranker_score: f64,
    ) !RewardSignal {
        if (!std.math.isFinite(graph_energy) or @abs(graph_energy) > MAX_GRAPH_ENERGY) {
            return error.InvalidGraphEnergy;
        }

        if (!std.math.isFinite(crev_confidence) or
            crev_confidence < MIN_CONFIDENCE or
            crev_confidence > MAX_CONFIDENCE)
        {
            return error.InvalidCREVConfidence;
        }

        if (!std.math.isFinite(surprise_novelty) or
            surprise_novelty < MIN_REWARD_INPUT or
            surprise_novelty > MAX_REWARD_INPUT)
        {
            return error.InvalidSurpriseNovelty;
        }

        if (!std.math.isFinite(ranker_score) or
            ranker_score < MIN_CONFIDENCE or
            ranker_score > MAX_CONFIDENCE)
        {
            return error.InvalidRankerScore;
        }

        const graph_energy_delta = switch (self.config.graph_energy_direction) {
            .lower_is_better => self.previous_graph_energy - graph_energy,
            .higher_is_better => graph_energy - self.previous_graph_energy,
        };

        const energy_reward = std.math.clamp(
            0.5 + graph_energy_delta * self.config.graph_energy_scale,
            MIN_REWARD_INPUT,
            MAX_REWARD_INPUT,
        );

        const crev_delta = crev_confidence - self.previous_crev_confidence;
        const ranker_error = @abs(ranker_score - self.previous_ranker_score);
        const scaled_surprise = std.math.clamp(
            surprise_novelty * energy_reward,
            MIN_REWARD_INPUT,
            MAX_REWARD_INPUT,
        );

        const reward = try RewardSignal.compute(
            scaled_surprise,
            crev_delta,
            ranker_error,
        );

        self.previous_graph_energy = graph_energy;
        self.previous_crev_confidence = crev_confidence;
        self.previous_ranker_score = ranker_score;

        return reward;
    }
};

pub const OnlineParameterSet = struct {
    values: []f64,
    gradients: []f64,
    accumulated_gradients: []f64,
    element_count: usize,
    accumulation_count: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, source_values: []const f64) !OnlineParameterSet {
        if (source_values.len == 0) {
            return error.EmptyParameterSet;
        }

        const values = try allocator.dupe(f64, source_values);
        errdefer allocator.free(values);

        const gradients = try allocator.alloc(f64, source_values.len);
        errdefer allocator.free(gradients);

        const accumulated_gradients = try allocator.alloc(f64, source_values.len);
        errdefer allocator.free(accumulated_gradients);

        @memset(gradients, 0.0);
        @memset(accumulated_gradients, 0.0);

        return .{
            .values = values,
            .gradients = gradients,
            .accumulated_gradients = accumulated_gradients,
            .element_count = source_values.len,
            .accumulation_count = 0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *OnlineParameterSet) void {
        self.allocator.free(self.values);
        self.allocator.free(self.gradients);
        self.allocator.free(self.accumulated_gradients);
    }

    pub fn clearGradients(self: *OnlineParameterSet) void {
        @memset(self.gradients, 0.0);
    }

    pub fn clearAccumulatedGradients(self: *OnlineParameterSet) void {
        @memset(self.accumulated_gradients, 0.0);
        self.accumulation_count = 0;
    }

    pub fn setGradient(self: *OnlineParameterSet, parameter_index: usize, gradient: f64) !void {
        if (parameter_index >= self.element_count or parameter_index >= self.values.len or parameter_index >= self.gradients.len) {
            return error.InvalidParameterIndex;
        }

        if (!std.math.isFinite(gradient)) {
            return error.NonFiniteGradient;
        }

        self.gradients[parameter_index] = gradient;
    }

    pub fn addGradient(self: *OnlineParameterSet, parameter_index: usize, gradient_delta: f64) !void {
        if (parameter_index >= self.element_count or parameter_index >= self.values.len or parameter_index >= self.gradients.len) {
            return error.InvalidParameterIndex;
        }

        if (!std.math.isFinite(gradient_delta)) {
            return error.NonFiniteGradient;
        }

        const updated_gradient = self.gradients[parameter_index] + gradient_delta;

        if (!std.math.isFinite(updated_gradient)) {
            return error.NonFiniteGradient;
        }

        self.gradients[parameter_index] = updated_gradient;
    }

    pub fn accumulate(self: *OnlineParameterSet, reward: f64) !void {
        if (self.values.len != self.element_count or
            self.gradients.len != self.element_count or
            self.accumulated_gradients.len != self.element_count)
        {
            return error.ParameterSetDimensionMismatch;
        }

        if (!std.math.isFinite(reward)) {
            return error.NonFiniteRewardInput;
        }

        if (self.accumulation_count >= MAX_SAFE_ACCUMULATION_STEPS) {
            return error.AccumulationLimitExceeded;
        }

        const scale = std.math.clamp(reward, -1.0, 1.0);

        for (self.gradients, self.accumulated_gradients) |gradient, *accumulated_gradient| {
            const updated_accumulated_gradient = accumulated_gradient.* + gradient * scale;

            if (!std.math.isFinite(updated_accumulated_gradient)) {
                return error.NonFiniteAccumulatedGradient;
            }

            accumulated_gradient.* = updated_accumulated_gradient;
        }

        self.accumulation_count += 1;
        self.clearGradients();
    }

    pub fn averageAccumulatedGradients(self: *OnlineParameterSet) !void {
        if (self.accumulation_count == 0) {
            return error.NoAccumulatedGradients;
        }

        if (self.accumulation_count > MAX_SAFE_ACCUMULATION_STEPS) {
            return error.AccumulationLimitExceeded;
        }

        const divisor: f64 = @floatFromInt(self.accumulation_count);

        if (!std.math.isFinite(divisor) or divisor <= 0.0) {
            return error.InvalidAccumulationDivisor;
        }

        for (self.accumulated_gradients) |*gradient| {
            gradient.* /= divisor;

            if (!std.math.isFinite(gradient.*)) {
                return error.NonFiniteAveragedGradient;
            }
        }
    }
};

pub const OnlineOptimizationConfig = struct {
    sfd_learning_rate: f64,
    esso_iterations: usize,
    esso_initial_temperature: f64,
    esso_cooling_rate: f64,
    accumulation_steps: usize,
    initial_parameter_set_capacity: usize,

    pub fn default() OnlineOptimizationConfig {
        return .{
            .sfd_learning_rate = 1e-5,
            .esso_iterations = 32,
            .esso_initial_temperature = 0.05,
            .esso_cooling_rate = 0.95,
            .accumulation_steps = ACCUMULATION_STEPS,
            .initial_parameter_set_capacity = 8,
        };
    }

    pub fn validate(self: OnlineOptimizationConfig) !void {
        if (!std.math.isFinite(self.sfd_learning_rate) or
            self.sfd_learning_rate < MIN_SFD_LEARNING_RATE or
            self.sfd_learning_rate > MAX_SFD_LEARNING_RATE)
        {
            return error.InvalidSFDLearningRate;
        }

        if (self.esso_iterations == 0) {
            return error.InvalidESSOIterations;
        }

        if (!std.math.isFinite(self.esso_initial_temperature) or self.esso_initial_temperature <= 0.0) {
            return error.InvalidESSOTemperature;
        }

        if (!std.math.isFinite(self.esso_cooling_rate) or
            self.esso_cooling_rate <= 0.0 or
            self.esso_cooling_rate >= 1.0)
        {
            return error.InvalidESSOCoolingRate;
        }

        if (self.accumulation_steps == 0 or self.accumulation_steps > MAX_SAFE_ACCUMULATION_STEPS) {
            return error.InvalidAccumulationSteps;
        }
    }
};

pub const OnlineOptimizer = struct {
    sfd_optimizer: sfd.SpectralFisherDescent,
    esso_optimizer: esso.EntangledStochasticSymmetryOptimizer,
    parameter_sets: std.ArrayList(OnlineParameterSet),
    config: OnlineOptimizationConfig,
    update_count: u64,
    mutex: std.Thread.Mutex,
    allocator: Allocator,

    pub fn init(
        allocator: Allocator,
        config: OnlineOptimizationConfig,
    ) !OnlineOptimizer {
        try config.validate();

        var parameter_sets = std.ArrayList(OnlineParameterSet).init(allocator);
        errdefer parameter_sets.deinit();

        try parameter_sets.ensureTotalCapacity(config.initial_parameter_set_capacity);

        var sfd_optimizer = try sfd.SpectralFisherDescent.init(allocator, config.sfd_learning_rate);
        errdefer sfd_optimizer.deinit();

        var esso_optimizer = esso.EntangledStochasticSymmetryOptimizer.init(
            allocator,
            config.esso_initial_temperature,
            config.esso_cooling_rate,
            config.esso_iterations,
        );
        errdefer esso_optimizer.deinit();

        return .{
            .sfd_optimizer = sfd_optimizer,
            .esso_optimizer = esso_optimizer,
            .parameter_sets = parameter_sets,
            .config = config,
            .update_count = 0,
            .mutex = .{},
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *OnlineOptimizer) void {
        self.mutex.lock();

        for (self.parameter_sets.items) |*parameter_set| {
            parameter_set.deinit();
        }

        self.parameter_sets.deinit();
        self.sfd_optimizer.deinit();
        self.esso_optimizer.deinit();

        self.mutex.unlock();
    }

    pub fn registerParameterSet(self: *OnlineOptimizer, source_values: []const f64) !usize {
        var parameter_set = try OnlineParameterSet.init(self.allocator, source_values);
        errdefer parameter_set.deinit();

        self.mutex.lock();
        defer self.mutex.unlock();

        try self.parameter_sets.append(parameter_set);
        return self.parameter_sets.items.len - 1;
    }

    pub fn clearGradients(self: *OnlineOptimizer, parameter_set_index: usize) !void {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (parameter_set_index >= self.parameter_sets.items.len) {
            return error.InvalidParameterSetIndex;
        }

        self.parameter_sets.items[parameter_set_index].clearGradients();
    }

    pub fn setGradient(
        self: *OnlineOptimizer,
        parameter_set_index: usize,
        parameter_index: usize,
        gradient: f64,
    ) !void {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (parameter_set_index >= self.parameter_sets.items.len) {
            return error.InvalidParameterSetIndex;
        }

        try self.parameter_sets.items[parameter_set_index].setGradient(parameter_index, gradient);
    }

    pub fn addGradient(
        self: *OnlineOptimizer,
        parameter_set_index: usize,
        parameter_index: usize,
        gradient_delta: f64,
    ) !void {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (parameter_set_index >= self.parameter_sets.items.len) {
            return error.InvalidParameterSetIndex;
        }

        try self.parameter_sets.items[parameter_set_index].addGradient(parameter_index, gradient_delta);
    }

    pub fn accumulateRewardedGradients(
        self: *OnlineOptimizer,
        parameter_set_index: usize,
        reward: RewardSignal,
    ) !void {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (parameter_set_index >= self.parameter_sets.items.len) {
            return error.InvalidParameterSetIndex;
        }

        try self.parameter_sets.items[parameter_set_index].accumulate(reward.combined);
    }

    fn takePendingUpdate(
        self: *OnlineOptimizer,
        parameter_set_index: usize,
    ) !struct {
        values: []f64,
        gradients: []f64,
        has_update: bool,
    } {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (parameter_set_index >= self.parameter_sets.items.len) {
            return error.InvalidParameterSetIndex;
        }

        const parameter_set = &self.parameter_sets.items[parameter_set_index];

        if (parameter_set.accumulation_count == 0) {
            return .{
                .values = parameter_set.values,
                .gradients = parameter_set.accumulated_gradients,
                .has_update = false,
            };
        }

        if (parameter_set.accumulation_count < self.config.accumulation_steps) {
            return .{
                .values = parameter_set.values,
                .gradients = parameter_set.accumulated_gradients,
                .has_update = false,
            };
        }

        try parameter_set.averageAccumulatedGradients();

        return .{
            .values = parameter_set.values,
            .gradients = parameter_set.accumulated_gradients,
            .has_update = true,
        };
    }

    fn clearAppliedUpdate(self: *OnlineOptimizer, parameter_set_index: usize) !void {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (parameter_set_index >= self.parameter_sets.items.len) {
            return error.InvalidParameterSetIndex;
        }

        const parameter_set = &self.parameter_sets.items[parameter_set_index];
        parameter_set.clearAccumulatedGradients();
        parameter_set.clearGradients();
        self.update_count += 1;
    }

    pub fn applySFD(self: *OnlineOptimizer, parameter_set_index: usize) !bool {
        const pending_update = try self.takePendingUpdate(parameter_set_index);

        if (!pending_update.has_update) {
            return false;
        }

        try self.sfd_optimizer.step(
            pending_update.values,
            pending_update.gradients,
        );

        try self.clearAppliedUpdate(parameter_set_index);
        return true;
    }

    pub fn optimizeESSO(
        self: *OnlineOptimizer,
        graph_context: *esso.GraphContext,
    ) !void {
        try self.esso_optimizer.optimize(graph_context);
    }

    pub fn applySFDAndESSO(
        self: *OnlineOptimizer,
        parameter_set_index: usize,
        graph_context: *esso.GraphContext,
    ) !bool {
        const applied = try self.applySFD(parameter_set_index);

        if (!applied) {
            return false;
        }

        try self.optimizeESSO(graph_context);
        return true;
    }

    pub fn flushSFD(self: *OnlineOptimizer, parameter_set_index: usize) !bool {
        self.mutex.lock();

        if (parameter_set_index >= self.parameter_sets.items.len) {
            self.mutex.unlock();
            return error.InvalidParameterSetIndex;
        }

        const parameter_set = &self.parameter_sets.items[parameter_set_index];

        if (parameter_set.accumulation_count == 0) {
            self.mutex.unlock();
            return false;
        }

        try parameter_set.averageAccumulatedGradients();

        const values = parameter_set.values;
        const gradients = parameter_set.accumulated_gradients;

        self.mutex.unlock();

        try self.sfd_optimizer.step(values, gradients);

        try self.clearAppliedUpdate(parameter_set_index);
        return true;
    }

    pub fn parameterSetCount(self: *OnlineOptimizer) usize {
        self.mutex.lock();
        defer self.mutex.unlock();

        return self.parameter_sets.items.len;
    }

    pub fn getUpdateCount(self: *OnlineOptimizer) u64 {
        self.mutex.lock();
        defer self.mutex.unlock();

        return self.update_count;
    }
};

pub const OnlineLearningController = struct {
    optimizer: OnlineOptimizer,
    reward_computer: InternalRewardComputer,
    allocator: Allocator,

    pub fn init(
        allocator: Allocator,
        optimization_config: OnlineOptimizationConfig,
        reward_config: InternalRewardConfig,
    ) !OnlineLearningController {
        var optimizer = try OnlineOptimizer.init(allocator, optimization_config);
        errdefer optimizer.deinit();

        const reward_computer = try InternalRewardComputer.init(reward_config);

        return .{
            .optimizer = optimizer,
            .reward_computer = reward_computer,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *OnlineLearningController) void {
        self.optimizer.deinit();
    }

    pub fn registerParameters(self: *OnlineLearningController, values: []const f64) !usize {
        return self.optimizer.registerParameterSet(values);
    }

    pub fn recordGradient(
        self: *OnlineLearningController,
        parameter_set_index: usize,
        parameter_index: usize,
        gradient: f64,
    ) !void {
        try self.optimizer.addGradient(parameter_set_index, parameter_index, gradient);
    }

    pub fn commitInteraction(
        self: *OnlineLearningController,
        parameter_set_index: usize,
        graph_context: *esso.GraphContext,
        graph_energy: f64,
        crev_confidence: f64,
        surprise_novelty: f64,
        ranker_score: f64,
    ) !bool {
        const reward = try self.reward_computer.computeReward(
            graph_energy,
            crev_confidence,
            surprise_novelty,
            ranker_score,
        );

        try self.optimizer.accumulateRewardedGradients(parameter_set_index, reward);

        return try self.optimizer.applySFDAndESSO(parameter_set_index, graph_context);
    }

    pub fn flush(
        self: *OnlineLearningController,
        parameter_set_index: usize,
        graph_context: *esso.GraphContext,
    ) !bool {
        const applied = try self.optimizer.flushSFD(parameter_set_index);

        if (!applied) {
            return false;
        }

        try self.optimizer.optimizeESSO(graph_context);
        return true;
    }
};
